        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('12021111-0000-4000-8000-000000000001', 'Which liquid pair forms an ideal solution obeying Raoult''s Law over all concentrations?', '{"A":"Ethanol + Water","B":"n-Hexane + n-Heptane (and Benzene + Toluene)","C":"Chloroform + Acetone","D":"HNO₃ + Water"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Solutions', 1, 'Nearly identical intermolecular A-B, A-A, B-B forces give ΔH_mix = 0, ΔV_mix = 0.', NULL, NULL, 'Nearly identical intermolecular A-B, A-A, B-B forces give ΔH_mix = 0, ΔV_mix = 0.', 'EASY', true),
        ('12021111-0000-4000-8000-000000000002', 'A mixture of Chloroform and Acetone shows negative deviation from Raoult''s Law because:', '{"A":"They repel each other","B":"H-bonding forms between C–H of chloroform and C=O oxygen of acetone, lowering vapour pressure","C":"Acetone evaporates faster","D":"ΔH_mix > 0"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Solutions', 1, 'Stronger A-B H-bond lowers escaping tendency -> maximum boiling azeotrope.', NULL, NULL, 'Stronger A-B H-bond lowers escaping tendency -> maximum boiling azeotrope.', 'EASY', true),
        ('12021111-0000-4000-8000-000000000003', 'Van''t Hoff factor (i) for completely dissociated K₂SO₄ in dilute aqueous solution is:', '{"A":"2","B":"3","C":"4","D":"1"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Solutions', 1, 'K₂SO₄ -> 2K⁺ + SO₄²⁻ gives 3 ions (i = 3).', NULL, NULL, 'K₂SO₄ -> 2K⁺ + SO₄²⁻ gives 3 ions (i = 3).', 'EASY', true),
        ('12021111-0000-4000-8000-000000000004', 'Which colligative property is preferred for determining molar mass of polymers and proteins?', '{"A":"Elevation in boiling point","B":"Osmotic Pressure (Π = CRT)","C":"Relative lowering of VP","D":"Depression in freezing point"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Solutions', 1, 'Measurable pressure in mm/cm at room temperature without denaturing biomolecules.', NULL, NULL, 'Measurable pressure in mm/cm at room temperature without denaturing biomolecules.', 'EASY', true),
        ('12021111-0000-4000-8000-000000000005', 'According to Henry''s Law (p = K_H x), higher value of K_H at a given pressure means:', '{"A":"Higher gas solubility","B":"Lower gas solubility in the liquid","C":"No temperature effect","D":"Zero equilibrium"}'::jsonb, 'B', 'MCQ', 'Chemistry', 'Solutions', 1, 'x = p / K_H -> inversely proportional to K_H (aquatic species prefer cold water).', NULL, NULL, 'x = p / K_H -> inversely proportional to K_H (aquatic species prefer cold water).', 'EASY', true),
        ('12021111-0000-4000-8000-000000000006', 'Assertion (A): When red blood cells are placed in 0.9% (w/v) NaCl saline solution, they neither swell nor shrink.
